:root {
  --rv-accent: oklch(0.5196 0.1248 247.06);
  --rv-accent-soft: oklch(0.5196 0.1248 247.06 / 0.094);
  --rv-bg: oklch(0.99 0.004 70);
  --rv-bg-chart: oklch(0.985 0.004 70);
  --rv-bg-elev: oklch(0.975 0.005 70);
  --rv-block-gap: 4rem;
  --rv-brand: oklch(0.5196 0.1248 247.06);
  --rv-chart-ink: oklch(0 0 0);
  --rv-density: 1;
  --rv-down: oklch(0.50 0.16 25);
  --rv-font-display: "RichView Serif", Georgia, serif;
  --rv-font-mono: RichView Code, ui-monospace, monospace;
  --rv-font-text: "RichView Serif", Georgia, serif;
  --rv-font-ui: "RichView Sans", system-ui, sans-serif;
  --rv-hold: oklch(0.55 0.13 70);
  --rv-ink: oklch(0.18 0.006 70);
  --rv-ink-faint: oklch(0.62 0.008 70);
  --rv-ink-soft: oklch(0.42 0.008 70);
  --rv-line-base: 1.65;
  --rv-link: oklch(0.5196 0.1248 247.06);
  --rv-measure: 42rem;
  --rv-radius-m: 2px;
  --rv-radius-s: 2px;
  --rv-report-max-width: 880px;
  --rv-rule: oklch(0.88 0.006 70);
  --rv-rule-soft: oklch(0.93 0.005 70);
  --rv-shadow-float: 0 2px 8px oklch(0 0 0 / 0.12);
  --rv-size-base: 16.5px;
  --rv-size-display: 44px;
  --rv-size-h1: 36px;
  --rv-size-h2: 28px;
  --rv-size-h3: 20px;
  --rv-size-small: 13.75px;
  --rv-up: oklch(0.45 0.12 150);
}
@media (max-width: 640px) {
:root {
  --rv-block-gap: 2.5rem;
  --rv-size-base: 16.5px;
  --rv-size-display: 36px;
  --rv-size-h1: 32px;
  --rv-size-h2: 28px;
  --rv-size-h3: 20px;
  --rv-size-small: 13.75px;
}
}
:root{color-scheme:light}
:root{--rv-motion-duration:240ms;--rv-motion-easing:cubic-bezier(0.4,0,0.2,1);--rv-motion-stagger:16ms;--rv-motion-distance:0px;--rv-motion-block:fade}
.rv-report__body blockquote{font-style:italic}
.rv-report__lede,.rv-report__subtitle{font-style:italic}
.rv-metric{border-bottom:1px solid var(--rv-rule);padding-bottom:calc(var(--rv-line) * .5 * var(--rv-density))}
.rv-callout{border-top-width:2px}
.rv-chart{display:flex;flex-direction:column}.rv-chart>*{order:5}.rv-chart .rv-chart__head{display:contents}.rv-chart .rv-chart__titlerow{order:1}.rv-chart .rv-chart__subtitle{order:8;flex:none}.rv-chart--expanded>.rv-chart__actions{order:3;align-self:flex-end;margin-left:0;justify-content:flex-end}.rv-chart .rv-chart__method{order:9}
.rv-chart .rv-chart__subtitle{border:1px solid var(--rv-rule);padding:.5rem .75rem;margin-top:.5rem}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
